package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.nbt.*;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.world.phys.Vec3;import java.util.*;
public record NtTunnel(UUID id,UUID owner,long revision,String dimension,NtGeometry.Plan plan,int iron,int string,int chains){
 public NtTunnel{if(revision<0||dimension.length()>128||iron<0||string<0||chains<0)throw new IllegalArgumentException("Invalid tunnel record");}
 public static CompoundTag planTag(NtGeometry.Plan p){CompoundTag n=new CompoundTag();var s=p.settings();n.putDouble("width",s.width());n.putDouble("height",s.height());n.putDouble("spacing",s.spacing());n.putDouble("trim",s.trim());n.putBoolean("sides",s.sides());n.putDouble("lift",p.lift());ListTag points=new ListTag();for(Vec3 v:p.points()){ListTag a=new ListTag();a.add(DoubleTag.valueOf(v.x));a.add(DoubleTag.valueOf(v.y));a.add(DoubleTag.valueOf(v.z));points.add(a);}n.put("points",points);ListTag left=new ListTag(),right=new ListTag(),errors=new ListTag();for(double d:p.left())left.add(DoubleTag.valueOf(d));for(double d:p.right())right.add(DoubleTag.valueOf(d));for(String e:p.errors())errors.add(StringTag.valueOf(e));n.put("left",left);n.put("right",right);n.put("errors",errors);return n;}
 public static NtGeometry.Plan readPlan(CompoundTag n){var pts=n.getList("points",9);if(pts.size()>64)throw new IllegalArgumentException("Too many points");List<Vec3> p=new ArrayList<>();for(int i=0;i<pts.size();i++){ListTag v=pts.getList(i);if(v.size()!=3)throw new IllegalArgumentException("Point requires XYZ");p.add(new Vec3(v.getDouble(0),v.getDouble(1),v.getDouble(2)));}var l=n.getList("left",6);var r=n.getList("right",6);if(l.size()>2048||r.size()>2048)throw new IllegalArgumentException("Too many support pairs");List<Double> left=new ArrayList<>(),right=new ArrayList<>();for(int i=0;i<l.size();i++)left.add(l.getDouble(i));for(int i=0;i<r.size();i++)right.add(r.getDouble(i));List<String> errors=new ArrayList<>();var e=n.getList("errors",8);for(int i=0;i<Math.min(8,e.size());i++)errors.add(e.getString(i));var s=new NtGeometry.Settings(n.getDouble("width"),n.getDouble("height"),n.getDouble("spacing"),n.getDouble("trim"),n.getBoolean("sides"));double lift=n.getDouble("lift");if(!Double.isFinite(lift)||Math.abs(lift)>32)throw new IllegalArgumentException("Invalid clearance lift");for(double d:left)if(!Double.isFinite(d))throw new IllegalArgumentException("Invalid foot");for(double d:right)if(!Double.isFinite(d))throw new IllegalArgumentException("Invalid foot");return new NtGeometry.Plan(p,s,lift,left,right,errors);}
 public CompoundTag save(){var n=new CompoundTag();n.putUUID("id",id);n.putUUID("owner",owner);n.putLong("revision",revision);n.putString("dimension",dimension);n.put("plan",planTag(plan));n.putInt("iron",iron);n.putInt("string",string);n.putInt("chains",chains);return n;}
 public static NtTunnel load(CompoundTag n){return new NtTunnel(n.getUUID("id"),n.getUUID("owner"),n.getLong("revision"),n.getString("dimension"),readPlan(n.getCompound("plan")),n.getInt("iron"),n.getInt("string"),n.getInt("chains"));}
 public NtTunnel revision(long rev){return new NtTunnel(id,owner,rev,dimension,plan,iron,string,chains);}
 public static void writePoints(FriendlyByteBuf b,List<Vec3> pts){b.writeVarInt(pts.size());for(Vec3 v:pts){b.writeDouble(v.x);b.writeDouble(v.y);b.writeDouble(v.z);}}
 public static List<Vec3> readPoints(FriendlyByteBuf b){int n=b.readVarInt();if(n<0||n>64)throw new IllegalArgumentException("Point count limit");List<Vec3> r=new ArrayList<>();for(int i=0;i<n;i++)r.add(new Vec3(b.readDouble(),b.readDouble(),b.readDouble()));return r;}
}
